UPDATE schedule_plan
status = #{status}, optimization_factor = #{optimizationFactor}, max_iterations_running = #{maxIterationsRunning}, iteration_delay_sec = #{iterationDelaySec}, external_id = #{externalId}, updated_at = now()
WHERE id = #{id}

UPDATE resource_booking
   SET status = 'done', updated_at = now()
 WHERE tenant_id = #{t}
   AND source_type = #{sourceType}
   AND source_id = #{sourceId}
   AND status IN ('planned', 'active')
   AND deleted_at IS NULL
